import { existsSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { spawnSync } from 'node:child_process';

export interface AuthPayload {
  userId: number;
  accessToken: string;
  refreshToken?: string;
  deviceUuid: string;
  savedAt?: string;
  raw?: unknown;
  authPath?: string;
}

export interface CreateAuthByQROptions {
  authPath?: string;
  deviceUuid?: string;
  deviceName?: string;
  modelName?: string;
  forced?: boolean;
  checkAllowlist?: boolean;
  enforceAllowlist?: boolean;
  appVer?: string;
  onQrUrl?: (url: string) => void;
  onPasscode?: (passcode: string) => void;
  save?: boolean;
}

type KakaoForgeApi = {
  createAuthByQR(options?: CreateAuthByQROptions): Promise<AuthPayload>;
  createClient(config?: Record<string, unknown>): any;
};

function findInstalledPackage(): string | null {
  let dir = process.cwd();
  while (true) {
    const candidate = join(dir, 'node_modules', 'kakaoforge');
    if (existsSync(candidate)) return candidate;
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

function load(): KakaoForgeApi {
  let packageRoot = findInstalledPackage();
  if (!packageRoot) {
    const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm';
    console.log('[KakaoForge] package missing; running npm install once...');
    const result = spawnSync(npm, ['install'], {
      cwd: process.cwd(),
      stdio: 'inherit',
      env: { ...process.env, npm_config_fund: 'false', npm_config_audit: 'false' },
    });
    if (result.status !== 0) {
      throw new Error(`KakaoForge install failed (exit ${result.status ?? 1}). Run npm install and retry.`);
    }
    packageRoot = findInstalledPackage();
  }
  if (!packageRoot) {
    throw new Error('KakaoForge package is unavailable after npm install.');
  }
  const require = createRequire(join(packageRoot, 'package.json'));
  return require(packageRoot) as KakaoForgeApi;
}

export function createAuthByQR(options?: CreateAuthByQROptions): Promise<AuthPayload> {
  return load().createAuthByQR(options);
}

export function createClient(config?: Record<string, unknown>): any {
  return load().createClient(config);
}
